"""Column and constraint helpers shared by the table models."""

from __future__ import annotations

import uuid
from typing import Any

from sqlalchemy import CheckConstraint, ForeignKey, Numeric, Uuid
from sqlalchemy.orm import Mapped, mapped_column

from kako.db.enums import ENUMS

# Money is BIGINT centavos; rates are NUMERIC(9,6) fractions (docs/data-model.md, Conventions).
RATE = Numeric(9, 6)


def uuid_pk() -> Mapped[uuid.UUID]:
    """A UUID primary key, generated by the backend (never by the database)."""
    return mapped_column(Uuid, primary_key=True)


def fk(target: str, *, nullable: bool = False, unique: bool = False, deferred: bool = False) -> Any:
    """A UUID foreign key column to `target` (`table.column`).

    `deferred` checks the key at commit instead of at each statement, for the one pair of tables
    that point at each other (a decision and its chosen option), which are written together.
    """
    key = (
        ForeignKey(target, deferrable=True, initially="DEFERRED", use_alter=True)
        if deferred
        else ForeignKey(target)
    )
    return mapped_column(Uuid, key, nullable=nullable, unique=unique or None)


def enum_check(table: str, column: str) -> CheckConstraint:
    """`column IN (...)` from the list in kako.db.enums.

    The values are constants in code, never input, so writing them into the DDL is safe.
    """
    values = ", ".join(f"'{value}'" for value in ENUMS[(table, column)])
    return CheckConstraint(f"{column} IN ({values})", name=column)


def one_value_check() -> CheckConstraint:
    """Exactly one of the five value columns is set (V-01, the part the database can check)."""
    return CheckConstraint(
        "num_nonnulls(value_money, value_rate, value_int, value_date, value_text) = 1",
        name="one_value",
    )


def value_range_check() -> CheckConstraint:
    """Money is never negative; a rate is a fraction between 0 and 1 (V-07)."""
    return CheckConstraint(
        "(value_money IS NULL OR value_money >= 0) AND "
        "(value_rate IS NULL OR (value_rate >= 0 AND value_rate <= 1))",
        name="value_range",
    )
